// Minimal `ms` stand-in for the loader's node_modules resolution test.
module.exports = function ms(value) {
  if (typeof value !== "string") return undefined;
  const match = /^(\d+(?:\.\d+)?)\s*(ms|s|m|h|d)?$/i.exec(value.trim());
  if (!match) return undefined;
  const amount = Number(match[1]);
  const unit = (match[2] || "ms").toLowerCase();
  const scale = { ms: 1, s: 1000, m: 60000, h: 3600000, d: 86400000 }[unit];
  return amount * scale;
};
